import{_ as e,o,c as a,a3 as d}from"./chunks/framework.cNy3aYYk.js";const h=JSON.parse('{"title":"Document-field TipTap — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Document-field TipTap — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/document-tiptap-fields-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Document-field TipTap — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/document-tiptap-fields-production-readiness"}]]},"headers":[],"relativePath":"deployment/document-tiptap-fields-production-readiness.md","filePath":"deployment/document-tiptap-fields-production-readiness.md","lastUpdated":1791151472000}'),n={name:"deployment/document-tiptap-fields-production-readiness.md"};function s(i,t,r,c,l,p){return o(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="document-field-tiptap-—-production-readiness-audit" tabindex="-1">Document-field TipTap — Production Readiness Audit <a class="header-anchor" href="#document-field-tiptap-—-production-readiness-audit" aria-label="Permalink to &quot;Document-field TipTap — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-03</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> after companion PR merge + migrate-first Backend + SPA/Mobile/Docs deploy + staging smoke</td></tr><tr><td><strong>Scope</strong></td><td>Shared TipTap <code>RichTextEditor</code> on document bodies only: announcements <code>body</code>, Help Desk ticket <code>description</code>, task/project <code>description</code>, activity <code>body</code>. Not notes, chat, addresses, SMS/WhatsApp templates, or automation JSON.</td></tr><tr><td><strong>Catalog</strong></td><td>announcements <strong>1.1.0 → 1.2.0</strong> · help-desk <strong>1.10.0 → 1.11.0</strong> · tasks <strong>1.6.0 → 1.7.0</strong> · projects <strong>1.6.0 → 1.7.0</strong> · activities <strong>1.1.0 → 1.2.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="./announcements">Announcements</a> · <a href="./help-desk">Help Desk</a> · <a href="./tasks">Tasks</a> · <a href="./projects">Projects</a> · <a href="/changelog/">CHANGELOG</a> · <a href="./upgrade">Upgrade</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Workspace document fields that people re-read (announcements, ticket descriptions, task/project descriptions, activity bodies) now use the existing Knowledge Base TipTap editor. HTML is stored as a string (Knowledge Base pattern — <strong>not</strong> billing <code>DocumentHtmlSanitizer</code>, which strips <code>style</code> and would drop text color). The SPA sanitizes with DOMPurify before <code>dangerouslySetInnerHTML</code>. Snippets, dashboard previews, notifications (<code>strip_tags</code>), and mobile <code>Text</code> use plain text.</p><p>Platform freeze is intact: no new shell, auth, or settings store. File a complaint stays a short textarea (plain text still round-trips into the HTML viewer).</p><p><strong>Go / No-Go:</strong> <strong>Go</strong>.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Editor reuse (<code>RichTextEditor</code>) — no new package</td><td><strong>Pass</strong></td></tr><tr><td>Display never unsanitized HTML</td><td><strong>Pass</strong> (A1, A4)</td></tr><tr><td>TipTap text color survives display sanitize</td><td><strong>Pass</strong> (A1)</td></tr><tr><td>Unsafe <code>javascript:</code> / <code>data:</code> link insert blocked</td><td><strong>Pass</strong> (A2)</td></tr><tr><td>Empty <code>&lt;p&gt;&lt;/p&gt;</code> not treated as content</td><td><strong>Pass</strong> (A3)</td></tr><tr><td>Catalog MINOR migrate-only (no <code>db:seed</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Pest HTML store + catalog bump</td><td><strong>Pass</strong></td></tr><tr><td>Vitest sanitize helpers</td><td><strong>Pass</strong></td></tr><tr><td>Docs user / API / developer / CHANGELOG / nav</td><td><strong>Pass</strong></td></tr><tr><td>Mobile TipTap</td><td><strong>Out of scope</strong> — strip tags on view/edit</td></tr><tr><td>File a complaint TipTap</td><td><strong>Out of scope</strong> (short note)</td></tr></tbody></table><hr><h2 id="audit-findings-initial-→-remediated" tabindex="-1">Audit findings (initial → remediated) <a class="header-anchor" href="#audit-findings-initial-→-remediated" aria-label="Permalink to &quot;Audit findings (initial → remediated)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Finding</th><th>Remediation</th></tr></thead><tbody><tr><td><strong>A1</strong></td><td>High</td><td><code>sanitizeKnowledgeBaseHtml</code> omitted <code>style</code>, so TipTap <strong>text color</strong> (inline <code>span style</code>) vanished on view even though it stored.</td><td><code>ADD_ATTR: [&#39;target&#39;, &#39;style&#39;]</code>. DOMPurify still strips scripts and <code>javascript:</code> hrefs.</td></tr><tr><td><strong>A2</strong></td><td>Medium</td><td>Link toolbar accepted any <code>href</code> (<code>javascript:</code>, <code>data:</code>).</td><td><code>isSafeRichTextHref</code> — <code>http</code> / <code>https</code> / <code>mailto</code> / same-origin path. Display sanitize remains a second gate.</td></tr><tr><td><strong>A3</strong></td><td>Medium</td><td><code>RichTextHtml</code> treated <code>&lt;p&gt;&lt;/p&gt;</code> as content; Help Desk gated on raw <code>ticket.description</code>.</td><td>Empty check uses <code>htmlToPlainText</code>.</td></tr><tr><td><strong>A4</strong></td><td>Medium</td><td>Inbox/view/dashboard could have shown raw tags before this ship.</td><td><code>RichTextHtml</code> on full bodies; <code>htmlToPlainText</code> / <code>htmlSnippet</code> on previews.</td></tr><tr><td><strong>A5</strong></td><td>Medium</td><td><code>AutomationEngineSupportTest</code> still expected payments <strong>1.4.0</strong> while CatalogSeeder is <strong>1.5.0</strong> — CI fail once this file is in the PR.</td><td>Companion map <strong>1.5.0</strong>.</td></tr><tr><td><strong>A6</strong></td><td>Low</td><td>Missing production-readiness page / VitePress / upgrade row.</td><td>This page + sidebar + upgrade + changelog link.</td></tr><tr><td><strong>I1</strong></td><td>Info</td><td>File a complaint description remains a textarea.</td><td><strong>Accepted</strong> — short dialog; stored plain text renders via <code>RichTextHtml</code>.</td></tr><tr><td><strong>I2</strong></td><td>Info</td><td>Mobile create/edit stay <code>FormTextarea</code>; HTML from web is stripped for display.</td><td><strong>Accepted</strong> (plan).</td></tr><tr><td><strong>I3</strong></td><td>Info</td><td>LIKE search can match HTML tags.</td><td><strong>Accepted</strong> — same as Knowledge Base.</td></tr></tbody></table><p>No High or Medium <strong>open</strong> residuals for ship.</p><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td>No new auth / tenancy / billing</td><td>Pass</td></tr><tr><td>HTML render only after DOMPurify</td><td>Pass</td></tr><tr><td>Scripts / forms / iframes forbidden on document HTML</td><td>Pass</td></tr><tr><td>Link insert allow-list</td><td>Pass</td></tr><tr><td>Notifications already <code>strip_tags</code> on announcement body</td><td>Pass</td></tr><tr><td>Tenant isolation unchanged</td><td>Pass</td></tr></tbody></table><hr><h2 id="change-inventory" tabindex="-1">Change inventory <a class="header-anchor" href="#change-inventory" aria-label="Permalink to &quot;Change inventory&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li>Migration <code>2026_10_03_182400_bump_document_rich_text_module_versions</code> — five MINOR catalog bumps</li><li><code>CatalogSeeder</code> versions aligned</li><li>Pest: announcement + Help Desk HTML store; catalog bump test; Automation companion versions</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li><code>RichTextHtml</code> + <code>htmlToPlainText</code> / <code>htmlSnippet</code></li><li>Forms: announcements, Help Desk, tasks, projects, activities</li><li>Display: view pages, announcement inbox, dashboard snippet, peeks</li><li>Playwright <code>fillRichText</code> helper</li><li>Vitest <code>src/lib/sanitize-html.test.ts</code></li></ul><h3 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h3><ul><li><code>lib/html.ts</code> <code>htmlToPlainText</code> on announcement/task/project/help-desk/activity view and edit load</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>User / API / developer guides; CHANGELOG; this audit; upgrade; VitePress</li></ul><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>herd php artisan test --compact tests/Feature/Central/Catalog/DocumentRichTextModuleVersionBumpTest.php</span></span>
<span class="line"><span>herd php artisan test --compact --filter=HTML tests/Feature/Tenant/Announcement/AnnouncementTest.php tests/Feature/Tenant/HelpDesk/HelpDeskTicketTest.php</span></span>
<span class="line"><span>npm run test:unit -- src/lib/sanitize-html.test.ts</span></span></code></pre></div><p><code>vendor/bin/pint --dirty --format agent</code> on Backend PHP changes.</p><p>Playwright: <code>test:e2e:announcements</code>, <code>test:e2e:help-desk</code>, <code>test:e2e:tasks</code>, <code>test:e2e:projects</code> (and activities if the suite fills body) after SPA deploy.</p><hr><h2 id="upgrade-staging-smoke" tabindex="-1">Upgrade &amp; staging smoke <a class="header-anchor" href="#upgrade-staging-smoke" aria-label="Permalink to &quot;Upgrade &amp; staging smoke&quot;">​</a></h2><ol><li>Deploy <strong>Backend</strong> and run <code>php artisan migrate --force</code> (<code>2026_10_03_182400_bump_document_rich_text_module_versions</code>). <strong>Do not</strong> <code>db:seed</code>.</li><li>Confirm catalog: announcements <strong>1.2.0</strong>, help-desk <strong>1.11.0</strong>, tasks <strong>1.7.0</strong>, projects <strong>1.7.0</strong>, activities <strong>1.2.0</strong>.</li><li>Deploy <strong>Frontend</strong>, then <strong>Mobile</strong> (OTA) and <strong>Docs</strong>.</li><li>Staging: <ul><li>Create a <strong>published</strong> announcement with heading, list, link, and red text → inbox dialog + record page render HTML (not tags); dashboard snippet is plain text; second user notification preview has no tags.</li><li>Edit a Help Desk ticket / task / project / activity description in TipTap → view page shows lists; peek snippet has no <code>&lt;p&gt;</code>.</li><li>Existing plain-text rows still load in the editor and display as text.</li><li>File a complaint still uses a textarea.</li><li>Mobile announcement/task view shows text without tags.</li></ul></li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Revert SPA first (stops HTML authoring). Catalog bump is display-only SemVer — leaving it is harmless. Stored HTML remains valid strings; a reverted SPA would show tags until re-deployed.</p><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Result</th></tr></thead><tbody><tr><td>Engineering</td><td><strong>Go</strong> after companion CI</td></tr><tr><td>Operator</td><td>Staging smoke above before production traffic</td></tr></tbody></table>`,37)])])}const u=e(n,[["render",s]]);export{h as __pageData,u as default};
